class AppStrings {
  static String t(BuildContext context, String key) {
    final settings = context.dependOnInheritedWidgetOfExactType<_LocaleScope>()?.settings;
    return _text(settings?.languageCode ?? 'fa', key);
  }

  static String forCode(String code, String key) => _text(code, key);

  static String _text(String code, String key) {
    final lang = code.split('-').first;
    final map = _translations[lang] ?? _translations['en']!;
    return map[key] ?? _translations['en']![key] ?? key;
  }

