class LocaleScope extends InheritedWidget {
  final AppSettings settings;
  const LocaleScope({super.key, required this.settings, required super.child});
  @override bool updateShouldNotify(LocaleScope oldWidget) => oldWidget.settings != settings || oldWidget.settings.languageCode != settings.languageCode;
}
